@test
def test_acceptance_ttest():
    bp, y = bp_data()
    t, pv = st.ttest_ind(bp[y == 0], bp[y == 1], axis=0)
    assert close(t, acc_t)
    assert close(pv, acc_p)
test_acceptance_ttest()

@test
def test_tests():
    a = np.array([1., 3., 2., 5., 4., 6.5, 2.2])
    b = np.array([2., 4.5, 3.1, 6., 5.5, 7.])
    c = np.array([4.1, 5.0, 3.3, 6.2])
    r = st.ttest_ind(a, b)
    assert close([r.statistic, r.pvalue, r.df], tti)
    r2 = st.ttest_ind(a, b, equal_var=False, alternative='less')
    assert close([r2.statistic, r2.pvalue, r2.df], tti_w)
    t, p = st.ttest_rel(a[:6], b)
    assert close([t, p], ttr)
    r3 = st.ttest_1samp(a, 2.0, alternative='greater')
    assert close([r3.statistic, r3.pvalue], tt1)
    r4 = st.pearsonr(a[:6], b)
    assert close([r4.statistic, r4.pvalue], pear)
    r5 = st.spearmanr(a[:6], b)
    assert close([r5.statistic, r5.pvalue], spear)
    lr = st.linregress(a[:6], b)
    assert close([lr.slope, lr.intercept, lr.rvalue, lr.pvalue, lr.stderr, lr.intercept_stderr], linr)
    r6 = st.f_oneway(a, b, c)
    assert close([r6.statistic, r6.pvalue], anova)
    r7 = st.kruskal(a, b, c)
    assert close([r7.statistic, r7.pvalue], krus)
    r8 = st.mannwhitneyu(a, b)
    assert close([r8.statistic, r8.pvalue], mwu_exact)
    r9 = st.mannwhitneyu(a, b, alternative='greater')
    assert close([r9.statistic, r9.pvalue], mwu_g)
    big1 = np.array([(i * 37 % 23) / 3.0 for i in range(15)])
    big2 = np.array([(i * 29 % 19) / 2.5 + 0.7 for i in range(12)])
    r10 = st.mannwhitneyu(big1, big2)
    assert close([r10.statistic, r10.pvalue], mwu_asym)
    d = np.array([0.5, -1.25, 2.0, 3.5, -0.75, 4.25, 1.5, -2.5, 5.0])
    r11 = st.wilcoxon(d)
    assert close([r11.statistic, r11.pvalue], wil_exact)
    r12 = st.wilcoxon(np.array([float(i * 13 % 17) - 7.3 for i in range(60)]))
    assert close([r12.statistic, r12.pvalue], wil_asym)
    r13 = st.chi2_contingency(np.array([[10, 20], [30, 25]]))
    assert close([r13.statistic, r13.pvalue], chi2c)
test_tests()

@test
def test_descriptive():
    a = np.array([1., 3., 2., 5., 4., 6.5, 2.2])
    assert close(st.zscore(a), zs)
    assert close(st.sem(a), sem)
    assert close(st.skew(a), skw)
    assert close(st.skew(a, bias=False), skw_ub)
    assert close(st.kurtosis(a, bias=False), kurt_ub)
    assert close(st.kurtosis(a, fisher=False), kurt)
    assert close(st.rankdata([3, 1, 3, 2, 1], method='min'), rank_min)
    assert close(st.rankdata([3, 1, 3, 2, 1]), rank_avg)
    assert close(st.rankdata([3, 1, 3, 2, 1], method='dense'), rank_dense)
    assert close(st.rankdata([3, 1, 3, 2, 1], method='ordinal'), rank_ord)
    D = st.describe(a)
    assert close([float(D.nobs), D.minmax[0], D.minmax[1], D.mean, D.variance, D.skewness, D.kurtosis], desc)
test_descriptive()

@test
def test_distributions():
    xs = np.array([-2.5, -0.3, 0.0, 0.7, 1.9, 4.2])
    qs = np.array([0.001, 0.1, 0.35, 0.5, 0.8, 0.999])
    xp = np.abs(xs) + 0.1
    assert close(st.norm.pdf(xs, 0.5, 1.5), n_pdf)
    assert close(st.norm.cdf(xs), n_cdf)
    assert close(st.norm.sf(xs, loc=1.0), n_sf)
    assert close(st.norm.ppf(qs, 2.0, 3.0), n_ppf)
    assert close(st.norm.isf(qs), n_isf)
    assert close(st.norm.logpdf(xs), n_logpdf)
    assert close(st.t.pdf(xs, 4.5), t_pdf)
    assert close(st.t.cdf(xs, 3), t_cdf)
    assert close(st.t.sf(xs, 10, loc=0.2, scale=1.3), t_sf)
    assert close(st.t.ppf(qs, 7), t_ppf)
    assert close(st.t(12).isf(qs), t_isf)
    assert close(st.t.logpdf(xs, 2.5), t_logpdf)
    assert close(st.chi2.pdf(xp, 3), c_pdf)
    assert close(st.chi2.cdf(xp, 4.5), c_cdf)
    assert close(st.chi2.sf(xp, 2), c_sf)
    assert close(st.chi2.ppf(qs, 5), c_ppf)
    assert close(st.chi2.isf(qs, 3), c_isf)
    assert close(st.f.pdf(xp, 3, 12), f_pdf)
    assert close(st.f.cdf(xp, 5, 7), f_cdf)
    assert close(st.f.sf(xp, 2, 30), f_sf)
    assert close(st.f.ppf(qs, 4, 9), f_ppf)
    assert close(st.f.isf(qs, 3, 15), f_isf)
    assert close(st.uniform.cdf(xs, -1.0, 4.0), u_cdf)
    assert close(st.uniform.pdf(xs, -1.0, 4.0), u_pdf)
    assert close(st.uniform.ppf(qs, 2.0, 0.5), u_ppf)
    assert close([st.t(5).mean(), st.t(5).var(), st.f(3, 12).mean(), st.f(3, 12).var(),
                  st.chi2(4).var(), st.uniform(1, 3).var(), st.norm(2, 3).std()], moms)
    assert close(st.norm.cdf(1.0), 0.8413447460685429)
    assert close(st.norm(1.0, 2.0).cdf(np.array([1.0])), [0.5])
test_distributions()

