@test
def test_followups():
    d = np.array([1., -2., 2., 3., -1., 0., 4., 1.5])
    got = [st.wilcoxon(d).pvalue, st.wilcoxon(d, zero_method='pratt').pvalue,
           st.wilcoxon(d, alternative='less').pvalue, st.wilcoxon(d, zero_method='zsplit').pvalue,
           st.wilcoxon(np.array([1., -2., 2., 3., -1., 5., 4., 1.5])).pvalue]
    assert close(got, wperm)
    a = np.array([1., 3., 2., 5., 4., 6.5, 2.2, 9.0, -1.0, 2.5])
    b = np.array([2., 4.5, 3.1, 6., 5.5, 7., 0.3, 3.3])
    r = st.ttest_ind(a, b, trim=0.2)
    assert close([r.statistic, r.pvalue, r.df], yuen)
    r2 = st.ttest_ind(a, b, trim=0.2, equal_var=False)
    assert close([r2.statistic, r2.pvalue, r2.df], yuen_w)
    X = np.arange(24.).reshape(6, 4) ** 1.3
    Y = np.arange(20.).reshape(5, 4) ** 1.1
    Z = np.cos(np.arange(16.)).reshape(4, 4) * 10
    assert close(st.f_oneway(X, Y, Z).pvalue, nd_anova_p)
    assert close(st.kruskal(X, Y, Z, axis=0).statistic, nd_krus)
    assert close(st.f_oneway(a, b, equal_var=False).pvalue, welch)
    assert close(st.f_oneway(X.T, Y.T, axis=1).statistic, nd_anova_ax1)
    W = np.array([[1., 4., 2.], [3., 1., 5.], [2., 6., 1.], [5., 2., 3.], [4., 3., 6.], [6., 5., 4.]])
    rs = st.spearmanr(W)
    assert close(rs.statistic, sp_mat)
    assert close(rs.pvalue, sp_mat_p)
test_followups()
